from base import *
def main():
 cfg=dict(name=ROOT.name,seed=20261018,frames=16,width=1920,height=1080,canvas=[1920,1088],QPs=[2,7],fps=30,force_zero_thres=.12,IP=-1,training=False,weights_modified=False,FID='NOT_COMPUTED_INSUFFICIENT_SAMPLES',primary_oracle_objective='sequence mean LPIPS',local_levels=[.5,1.,2.],q_floor=.5,control='experimental symmetric prior quant-step override; not native independent block QP',rate_match='EXACT actual total bytes only; nonzero deviations are not fair equal-rate comparisons',calibration='try adjacent legal global QPs, select by actual rate only; no padding',blocks=[dict(frame=f,y=y,x=x,h=8,w=8) for f in (2,8) for y,x in ((8,8),(30,56))],GPU_ids=[4,5,6,7],workers_per_GPU=1,minimum_free_MiB=7000)
 ev=load(V32/'eval_manifest.json');selected=[ev[d][0] for d in ('uvg_holdout','hevc_b','mcljcv','ulong')]
 for v in selected:
  assert Path(v['input_dir']).is_dir()
  v['selection']='first fixed inherited evaluation identity; no quality-based selection'
  v['historical_baselines']={str(q):str(V33/'evaluation/points'/f'{v["dataset"]}_{v["video_index"]}_A_noP_frozenReceiver_{q}.json') for q in cfg['QPs']}
  for p in v['historical_baselines'].values():assert load(p)['status']=='PASS'
 paths=[REPO/p for p in ['src/models/video_model_gvcrt.py','src/models/image_model_gvcrt.py','src/models/common_model.py','src/models/entropy_models.py','src/models/improved_model_gvcrt.py','src/layers/cuda_inference.py','src/cpp/py_rans/rans.cpp','src/utils/stream_helper.py','test_video_gvcrt_1088.py']]
 paths += [ENGINE,V32/'adapter32.py',V32/'training32.py',V32/'report32.py',V32/'evaluation_config.json',V33/'status.json',V33/'actual_bitstream_integrity.json',V33/'latent_interface_audit.json']
 source={str(p):dict(sha256=sha(p),bytes=p.stat().st_size) for p in paths if p.is_file()}
 checkpoints={str(p):dict(sha256=sha(p),bytes=p.stat().st_size) for p in [REPO/'checkpoints/GVC-RT_I.pt',REPO/'checkpoints/GVC-RT_P.pt']}
 expected=load(V33/'checkpoint_hashes.json')
 for p,v in checkpoints.items():assert v['sha256']==expected[Path(p).name]['sha256']
 git_head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip()
 dump('configs/experiment.json',cfg);dump('manifests/videos.json',selected);dump('manifests/weights.json',checkpoints)
 dump('audit/source_path_audit.json',dict(status='STATIC_AUDIT_COMPLETE_DYNAMIC_TEST_PENDING',git_HEAD=git_head,source_files=source,weights=checkpoints,encoder='DMC.enc: pixel-unshuffle8 then stride2 => y[1,128,68,120] on1088x1920',hyper='z[1,128,17,30]; round/clamp int8 then BitEstimator RANS',discretization='P y/q_dec minus conditional means: torch.round; force-zero scale threshold0.12; clamp[-128,127]; checkerboard2 groups. LFQ not used on actual P entropy-coded y path.',native_control='scalar frame QP + qp_shift[0,2,1] selects learned channel scales; prior also predicts spatial/channel q_dec>=0.5, no external arbitrary block-QP API',proposal='hook res_prior_param_decoder output quant-step channels identically at encoder and both decoders; keep all stock quantization, CDF, RANS and reference updates',legacy_protocol=load(V32/'evaluation_config.json'),no_existing_file_modified=True))
 notes={
 'quantization_control_audit.md':'# Quantization control\n\nNative API accepts one scalar QP per frame. Learned q_scale tensors are channelwise; the decoded prior produces a spatial/channel quant_step, clamped at0.5. There is no native independent block QP API. The experiment multiplies this decoded step within explicitly signalled latent-grid rectangles by0.5 or2, clamps at0.5, and passes the modified common_params into unchanged stock two-pass coding at both endpoints. The second checkerboard prior consumes the same modified common_params and first-group symbols at both endpoints. This is a custom codec-control extension, not a stock-decoder-compatible stream or arbitrary replacement of decoded symbols. Factor1 must preserve native bytes. QP shifts and all weights remain unchanged.\n',
 'entropy_coding_audit.md':'# Entropy coding\n\nUnchanged BitEstimator and GaussianEncoder use installed16-bit CDFs and native RANS. Native SPS/IP records and complete RANS payloads are retained. A versioned experiment envelope signals block frame/y/x/h/w and a discrete factor code using11 bytes per decision plus10 fixed bytes; the independent decoder reads this envelope, never an external oracle plan. Actual total bytes include native codec headers, all RANS payloads and control side information. These components are reported separately. No bit flips, post-hoc stream edits, estimated bits or decoder-only deletion enter real-rate comparisons.\n',
 'decoder_causality_audit.md':'# Decoder causality\n\nI0 seeds the P reference. Each P frame updates its decoded feature DPB; following encoding and decoding use that updated feature. Each intervention is re-encoded from I0 through all16 frames, including every affected suffix frame. Stock synchronized encoder/decoder features are checked exactly for every P frame, followed by a fresh independent decode from the persisted stream and exact per-frame reconstruction checks. Captured encoder packed symbols must equal both paired and independent entropy-decoded symbols at frames2 and8. No frozen-context single-frame proxy is substituted.\n'}
 for f,t in notes.items():(ROOT/'audit'/f).write_text(t)
 dump('experiment_manifest.json',dict(name=ROOT.name,status='PREPARED',config='configs/experiment.json',videos='manifests/videos.json',code_version=git_head,training_steps=0,weights='manifests/weights.json',source_audit='audit/source_path_audit.json',planned_baseline_runs=16,planned_local_interventions=64,planned_noop_correctness=1,planned_joint_validation=8,planned_strategies='A baseline,B seeded random,C temporal RGB difference,D exhaustive additive-surrogate oracle; each re-encoded and calibrated if needed',FID=cfg['FID']))
 (ROOT/'.gitignore').write_text('artifacts/\n__pycache__/\n*.tmp\n*.lock\n')
 (ROOT/'README.md').write_text('# GVC-RT recoverability oracle feasibility\n\nFixed original GVC-RT weights. No training, P module or weight updates. Four inherited evaluation identities;16 native-resolution frames;QP2/7. Audit and executable configuration are under audit/ and configs/.\n\nRun: `/Huang_group/zyyz/home_dir/.conda/envs/gvc-rt/bin/python -B src/driver.py` from this directory (GPU4/5/6/7 only). Individual commands and stdout/stderr are saved under logs/ and manifests/. Completed atomic receipts are resumable.\n\nBaseline: baseline/. Local interventions: oracle/local_sensitivity/. Allocation trials: oracle/rate_allocation/. Raw tensors, complete streams and lossless sample reconstructions: artifacts/ (not Git; indexed with server paths and SHA256). Metrics are computed from floating-point native reconstructions before video export. FID is not computed for these small pools. Experimental block control must pass decoder/causality correctness before allocation is enabled. Exact actual-rate matches are labelled separately from unmatched trials. See run_status.json for status; no population or optimality conclusions are made.\n')
 print('AUDIT PREPARED',flush=True)
if __name__=='__main__':main()
